from datetime import datetime


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict
        self._next_id = 1

    def _active_appointments(self):
        # Appointments that are still upcoming are those not cancelled
        # (we track everything; cancellation removes from dict)
        return self._appointments.values()

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Appointment cannot start in the past")
        if end <= start:
            raise ValueError("Appointment end must be after start")

        # Validate overlap with same doctor
        if not self.is_free(doctor, start, end):
            raise ValueError(
                f"Doctor {doctor} is not free between {start} and {end}"
            )

        # Validate patient upcoming appointment constraint
        for appt in self._appointments.values():
            if appt["patient"] == patient and appt["start"] >= now:
                raise ValueError(
                    f"Patient {patient} already has an upcoming appointment"
                )

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
        }
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError(f"Unknown appointment id: {appointment_id}")
        del self._appointments[appointment_id]

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            # Overlap check: half-open intervals [start, end)
            if start < appt["end"] and appt["start"] < end:
                return False
        return True
